-- Insert Quiz Questions for Lesson: Understand the Reputation Area

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 15 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 15 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'understand-reputation-area' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson understand-reputation-area not found in module 15';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which area is used to send and track review requests?', 
    '["Reputation → Overview","Reputation → Requests","Reputation → Reviews","Settings → General"]'::jsonb,
    'Reputation → Requests',
    'Reputation → Requests is where you send and track review requests to customers.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where is the main review link set?', 
    '["Reputation → Widgets","Settings → Review Link","Reputation → Requests","Automation → Workflows"]'::jsonb,
    'Settings → Review Link',
    'The main review link is set in Settings → Review Link, which determines where customers go when they click the review link.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
